#!/usr/bin/env python3
"""Writes the constant tables of the L chip algorithm as C headers for the microcontroller port (hw/mcu), from the RTL memory files in hw/rtl/deep, and the test images.
l_tables.h  : detector templates (128 x 25 bits), stage-1 table (4,608 x 10 int8), stage-2 code rows (4,608 x 10 int8), clause rows (2,000 x 10 int8), clause headers (start, count) and literals (13,497 x uint16).
test_images.bin : the first N Fashion-MNIST test images (784 bytes each) for the PC check; l_testimg.h : the first M of them, for the microcontroller firmware.
usage: python gen_tables.py DATA_DIR [N=200] [M=40]"""
import os, sys
import numpy as np
HERE = os.path.dirname(os.path.abspath(__file__)); DEEP = os.path.join(HERE, "..", "rtl", "deep"); sys.path.insert(0, os.path.join(HERE, "..", "brain"))
from cortex_core import load  # noqa
D = sys.argv[1]; N = int(sys.argv[2]) if len(sys.argv) > 2 else 200; M = int(sys.argv[3]) if len(sys.argv) > 3 else 40
rd = lambda f: [l.strip() for l in open(os.path.join(DEEP, f)) if l.strip()]
def rows(f):
    out = []
    for l in rd(f): out.append([int(l[2 * (9 - k):2 * (9 - k) + 2], 16) for k in range(10)])         # class 0 is the lowest byte
    a = np.array(out, np.int64); return np.where(a > 127, a - 256, a)
w1, w2, wcl = rows("deep_wcode1.hex"), rows("deep_wcode.hex"), rows("deep_wcl.hex")
hdr = [(int(l[:4], 16), int(l[4:], 16)) for l in rd("deep_hdr.hex")]; lits = [int(l, 16) for l in rd("deep_lits.hex")]; tm = [int(l, 16) for l in rd("tmpl.hex")]
assert w1.shape == (4608, 10) and w2.shape == (4608, 10) and wcl.shape == (len(hdr), 10) and len(tm) == 128
def arr(ctype, name, vals, per=24): return "static const %s %s[%d] = {\n%s\n};\n" % (ctype, name, len(vals), ",\n".join(",".join(str(int(v)) for v in vals[i:i + per]) for i in range(0, len(vals), per)))
with open(os.path.join(HERE, "l_tables.h"), "w") as f:
    f.write("/* generated by gen_tables.py from hw/rtl/deep: do not edit */\n#pragma once\n#include <stdint.h>\n#define L_NCL %d\n#define L_NLITS %d\n#define L_ROUTE_T 2299\n" % (len(hdr), len(lits)))
    f.write(arr("uint32_t", "L_TM", tm)); f.write(arr("int8_t", "L_W1", w1.reshape(-1))); f.write(arr("int8_t", "L_W2", w2.reshape(-1))); f.write(arr("int8_t", "L_WCL", wcl.reshape(-1)))
    f.write(arr("uint16_t", "L_HDR_START", [s for s, _ in hdr])); f.write(arr("uint8_t", "L_HDR_N", [n for _, n in hdr])); f.write(arr("uint16_t", "L_LITS", lits))
xtr, ytr, xte, yte = load(D, "fashion"); open(os.path.join(HERE, "test_images.bin"), "wb").write(xte[:N].astype(np.uint8).tobytes())
exp = [list(map(int, l.split())) for l in open(os.path.join(DEEP, "sys_exp.txt")) if l.strip()]
with open(os.path.join(HERE, "l_testimg.h"), "w") as f:
    f.write("/* generated by gen_tables.py: the first %d Fashion-MNIST test images and the expected prediction of the model for each */\n#pragma once\n#include <stdint.h>\n#define L_NTEST %d\n" % (M, M))
    f.write(arr("uint8_t", "L_TEST_IMG", xte[:M].astype(np.uint8).reshape(-1), 28)); f.write(arr("uint8_t", "L_TEST_PRED", [e[-1] for e in exp[:M]])); f.write(arr("uint8_t", "L_TEST_LABEL", yte[:M].astype(np.uint8)))
print("wrote l_tables.h (%d clauses, %d literals), test_images.bin (%d images), l_testimg.h (%d images)" % (len(hdr), len(lits), N, M))
